CREATE TABLE accounts (id BIGINT AUTO_INCREMENT PRIMARY KEY,email VARCHAR(150) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,password VARCHAR(255) NOT NULL,role VARCHAR(20) NOT NULL);
CREATE TABLE products(id BIGINT PRIMARY KEY,slug VARCHAR(160) NOT NULL UNIQUE,name VARCHAR(160) NOT NULL,category VARCHAR(60) NOT NULL,description VARCHAR(2000),image VARCHAR(700),active BOOLEAN NOT NULL);
CREATE TABLE variants(id BIGINT PRIMARY KEY,product_id BIGINT NOT NULL,size VARCHAR(80) NOT NULL,price BIGINT NOT NULL,stock INT NOT NULL,version BIGINT);
CREATE TABLE shop_orders(id BIGINT AUTO_INCREMENT PRIMARY KEY,account_id BIGINT NOT NULL,request_key VARCHAR(150) NOT NULL UNIQUE,recipient VARCHAR(100) NOT NULL,phone VARCHAR(20) NOT NULL,address VARCHAR(500) NOT NULL,note VARCHAR(500),status VARCHAR(20) NOT NULL,subtotal BIGINT NOT NULL,shipping BIGINT NOT NULL,total BIGINT NOT NULL,created_at TIMESTAMP(6) WITH TIME ZONE NOT NULL);
CREATE TABLE order_lines(id BIGINT AUTO_INCREMENT PRIMARY KEY,order_id BIGINT NOT NULL,variant_id BIGINT NOT NULL,product_name VARCHAR(160) NOT NULL,size VARCHAR(80) NOT NULL,image VARCHAR(700),quantity INT NOT NULL,unit_price BIGINT NOT NULL);
